/* ---------------- Spell catalog ----------------
   Every spell of the 2014 Player's Handbook (by level), then Xanathar's
   Guide and Tasha's Cauldron in their own blocks at the end. One entry
   per spell. Summaries are short paraphrases of the effect in plain
   sentences (full ability names, "feet", no semicolons), not the full
   rules text: enough to pick a spell and remember what it does. How a
   spell grows with level or slot is in spell-scaling.js, so summaries
   don't repeat it. The sheet lets players add their own notes. */
var SCHOOLS = {
  Abj:"Abjuration", Con:"Conjuration", Div:"Divination", Enc:"Enchantment",
  Evo:"Evocation", Ill:"Illusion", Nec:"Necromancy", Tra:"Transmutation"
};

/* s(level, school, castingTime, range, components, duration, classes, summary, opts)
   classes is a comma list; concentration is derived from the duration
   text; opts = {ritual:true, material:"…", tasha:"Bard,Ranger",
   source:"EGW"} for the rare extras (source: a spell from a book past the
   Player's Handbook, Xanathar's and Tasha's, see SPELL_SOURCES). tasha lists the classes that get the spell only through
   Tasha's optional Additional Spells feature (tashaClasses on the entry):
   it joins their list for characters using Tasha's optional features. */
function s(level, school, castingTime, range, components, duration, classes, summary, opts){
  opts = opts || {};
  return {
    level: level,
    school: SCHOOLS[school],
    castingTime: castingTime,
    range: range,
    components: components,
    material: opts.material || "",
    duration: duration,
    concentration: /^Concentration/.test(duration),
    ritual: !!opts.ritual,
    classes: classes ? classes.split(",") : [],
    tashaClasses: opts.tasha ? opts.tasha.split(",") : [],
    source: opts.source || "",
    summary: summary
  };
}

