/* Ranges corrected the same way (a saved spell also keeps its own range). */
export var SPELL_OLD_RANGES = {
  "Crusader's Mantle": ["Self"]
};
export function currentSpellRange(name, range){
  var d = SPELL_DATA[catalogSpellName(name)];
  var old = SPELL_OLD_RANGES[catalogSpellName(name)];
  return d && old && old.indexOf(range) !== -1 ? d.range : range;
}
export function currentSpellSummary(name, summary){
  var d = SPELL_DATA[catalogSpellName(name)];
  var old = SPELL_OLD_SUMMARIES[catalogSpellName(name)];
  return d && old && old.indexOf(summary) !== -1 ? d.summary : summary;
}

/* Book names that the catalog lists under their SRD name. */
export var SPELL_ALIASES = { "Melf's Acid Arrow": "Acid Arrow" };
export function catalogSpellName(name){ return SPELL_ALIASES[name] || name; }

/* ---- Derived views ---- */
export var SPELL_LEVEL_LABELS = ["Cantrip","1st Level","2nd Level","3rd Level","4th Level","5th Level","6th Level","7th Level","8th Level","9th Level"];

export function spellLevelLabel(level){ return SPELL_LEVEL_LABELS[level] || ("Level " + level); }

/* Mutable groups object: custom-spells.js merges its "Homebrew" group
   into this so the catalog picker sees homebrew spells alongside built-ins. */
export var SPELL_GROUPS = {};

/* True when the spell is on the class's list. `tasha` adds the spells
   Tasha's optional Additional Spells feature gives the class. */
export function spellOnClassList(d, className, tasha){
  return (d.classes||[]).indexOf(className) !== -1 || (!!tasha && tashaAddsSpell(d, className));
}
/* True when the class gets the spell only through Tasha's Additional Spells. */
export function tashaAddsSpell(d, className){
  return !!d && (d.tashaClasses||[]).indexOf(className) !== -1;
}
/* How many spells Tasha's Additional Spells adds to the class's list,
   optionally only of some spell levels. */
export function tashaSpellCount(className, levels){
  return Object.keys(SPELL_DATA).filter(function(name){
    var d = SPELL_DATA[name];
    return tashaAddsSpell(d, className) && (!levels || levels.indexOf(d.level) !== -1);
  }).length;
}

/* Names grouped by level label (only levels that have spells), sorted
   alphabetically; the shape the catalog picker expects. Pass a class
   name to limit the groups to that class's spell list (with Tasha's
   additions when `tasha` is set).
   Always includes any homebrew entries from SPELL_GROUPS["Homebrew"]. */
export function buildSpellGroups(className, tasha){
  var groups = {};
  Object.keys(SPELL_DATA).sort().forEach(function(name){
    var d = SPELL_DATA[name];
    if(className && !spellOnClassList(d, className, tasha)) return;
    var label = spellLevelLabel(d.level);
    (groups[label] = groups[label] || []).push(name);
  });
  // Append homebrew entries (they don't belong to any class list)
  if(!className && SPELL_GROUPS["Homebrew"] && SPELL_GROUPS["Homebrew"].length){
    groups["Homebrew"] = SPELL_GROUPS["Homebrew"].slice();
  }
  var ordered = {};
  SPELL_LEVEL_LABELS.forEach(function(label){ if(groups[label]) ordered[label] = groups[label]; });
  if(groups["Homebrew"]) ordered["Homebrew"] = groups["Homebrew"];
  return ordered;
}

/* Subset of SPELL_DATA for one class (same entries, just filtered). */
export function spellDataForClass(className, tasha){
  var out = {};
  Object.keys(SPELL_DATA).forEach(function(name){
    if(spellOnClassList(SPELL_DATA[name], className, tasha)) out[name] = SPELL_DATA[name];
  });
  return out;
}

/* Catalog spells of one spell level from any class's list, optionally
   only from some schools or only rituals, sorted by name. For picks that
   aren't tied to a class list: Fey Touched's 1st-level spell, Pact of the
   Tome's cantrips, Book of Ancient Secrets' rituals. */
export function spellsMatching(filter){
  return Object.keys(SPELL_DATA).filter(function(name){
    var d = SPELL_DATA[name];
    return d.level===filter.level && (!filter.schools || filter.schools.indexOf(d.school)!==-1) && (!filter.ritual || d.ritual);
  }).sort();
}
